#include <iostream>
#include <string>

class GeometricObject {
public:
  std::string toString() const {
    return "Geometric object";
  }
};

class Circle : public GeometricObject {
public:
  std::string toString() const {
    return "Circle object";
  }
};

class Rectangle : public GeometricObject {
public:
  std::string toString() const {
    return "Rectangle object";
  }
};

int main() {
  GeometricObject shape;
  Circle circle;
  Rectangle rectangle;

  std::cout << "shape.toString() returns " << shape.toString() << "\n";
  std::cout << "circle.toString() returns " << circle.toString() << "\n";
  std::cout << "rectangle.toString() returns " << rectangle.toString() << "\n";
  std::cout << "circle.GeometricObject::toString() returns " 
            << circle.GeometricObject::toString() << "\n";

  return 0;
}
